    email_domain: str | None = None,
    min_id: int | None = None,
    max_id: int | None = None,
) -> list[dict]:
    """Return users matching every given filter, ordered by id ascending."""
    clauses: list[str] = []
    args: list[object] = []
    if name_contains is not None:
        # instr() treats '%' and '_' as ordinary characters.
        clauses.append("instr(lower(name), lower(?)) > 0")
        args.append(name_contains)
    if email_domain is not None:
        # Compare the domain part (everything after '@') exactly, case-insensitively.
        clauses.append("lower(substr(email, instr(email, '@') + 1)) = lower(?)")
        args.append(email_domain)
    if min_id is not None:
        clauses.append("id >= ?")
        args.append(min_id)
    if max_id is not None:
        clauses.append("id <= ?")
        args.append(max_id)

    query = "SELECT id, name, email FROM users"
    if clauses:
        query += " WHERE " + " AND ".join(clauses)
    query += " ORDER BY id"
    rows = _conn.execute(query, args).fetchall()
    return [dict(row) for row in rows]"}

